const icon = (name, size=19) => `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name]||ICONS.file}</svg>`;
const esc = v => String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const readStore = (key, fallback) => {try{return JSON.parse(localStorage.getItem(`qx-desk-${key}`))??fallback}catch{return fallback}};
const writeStore = (key,value) => {try{localStorage.setItem(`qx-desk-${key}`,JSON.stringify(value));return true}catch{toast('無法儲存，請檢查瀏覽器儲存空間。');return false}};
