const defaults = {writingNotes:'',name:'千禧',tone:'口語清楚，避免過度官方',length:'重點分段，精簡但不省略必要資訊',notes:'使用繁體中文。步驟要具體、可以直接照做。不要捏造日期、金額、來源或已完成事項。設計採平塗、留白、少量配色。'};
const S = {view:'home',toolId:null,forms:{},files:{},workbookFiles:{},sheetIndex:0,headerRow:1,excelOptions:{},excelResult:null,output:'',filter:'all',search:'',prefs:{...defaults,...readStore('prefs',{})},favorites:readStore('favorites',['excel','official','social']),drafts:readStore('drafts',[]),recent:readStore('recent',[]),attachmentNotice:0};
let toastTimer, cardTimer, fileSequence=0;
const app = document.getElementById('app');
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3200)}
function currentTool(){return TOOLS.find(t=>t.id===S.toolId)}
function getForm(id=S.toolId){if(!S.forms[id]){const t=TOOLS.find(x=>x.id===id);S.forms[id]={title:'',objective:'',material:'',...Object.fromEntries(t.fields.map(([key,,type,options])=>[key,type==='select'?options[0]:'']))};}return S.forms[id]}
function localDate(value=new Date()){return new Intl.DateTimeFormat('zh-TW',{timeZone:'Asia/Taipei',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(value)}
function render(){
 const active=S.view==='workspace'?S.toolId:S.view;
 app.innerHTML=`<div class="mobile-overlay" data-action="close-menu"></div><aside class="sidebar" aria-label="主要選單"><button class="icon-button sidebar-close" data-action="close-menu" aria-label="關閉選單">${icon('x')}</button><a href="#home" class="brand" data-action="home"><span class="brand-icon">${icon('clipboard',24)}</span><span><strong>${esc(S.prefs.name)}的辦公桌</strong><small>YOUR EVERYDAY WORKSPACE</small></span></a><nav><button class="nav-btn ${active==='home'?'active':''}" data-action="home">${icon('home')}我的工作桌</button><button class="nav-btn ${active==='drafts'?'active':''}" data-action="drafts">${icon('folder')}我的工作草稿<span class="nav-badge">${S.drafts.length}</span></button></nav><div class="nav-label">工作工具</div><nav class="nav-tools">${TOOLS.map(t=>`<button class="nav-btn ${active===t.id?'active':''}" data-action="tool" data-id="${t.id}">${icon(t.icon,18)}${t.short}</button>`).join('')}</nav><div class="sidebar-footer"><button class="nav-btn" data-vault="open">${icon('folder',17)}資料與備份</button><button class="nav-btn" data-action="settings">${icon('settings',17)}我的使用偏好</button><div class="user-chip"><span class="avatar">${esc(S.prefs.name.charAt(0)||'千')}</span><div class="user-info">${esc(S.prefs.name)}的工作空間<small>這個瀏覽器上的個人工具</small></div>${icon('leaf',16)}</div></div></aside><div class="shell"><header class="topbar"><button class="icon-button mobile-menu" data-action="open-menu" aria-label="開啟選單">${icon('menu',20)}</button><div class="breadcrumb"><span>我的工作空間</span>${icon('chevron',12)}<strong>${S.view==='home'?'我的工作桌':S.view==='drafts'?'工作草稿':esc(currentTool()?.name)}</strong></div><div class="top-actions"><label class="search-box">${icon('search',15)}<input id="tool-search" type="search" placeholder="找一個工作工具" value="${esc(S.search)}" aria-label="搜尋工作工具"><span class="search-key">/</span></label><button class="help-trigger" data-action="help" aria-label="使用方式">${icon('help',17)}<span>使用方式</span></button></div></header><main class="content" id="main">${S.view==='home'?homeHTML():S.view==='drafts'?draftsHTML():workspaceHTML()}</main></div>`;
 if(S.view==='workspace'){if(S.toolId==='official'&&window.OfficeCases?.isActive()){window.OfficeCases.afterRender();return;}renderFiles();renderWorkbook();if(S.toolId==='design')renderCard();if(S.output)renderOutput();if(S.toolId==='official')window.OfficeCases?.decorateLegacy();}
}
function homeHTML(){return Workbench.home()}
function cardsHTML(){const q=S.search.trim().toLowerCase();const items=TOOLS.filter(t=>(S.filter!=='favorites'||S.favorites.includes(t.id))&&(!q||`${t.name} ${t.desc} ${t.keywords}`.toLowerCase().includes(q)));return items.length?items.map(t=>`<article class="tool-card" data-tool="${t.id}"><button class="card-main-link" data-action="tool" data-id="${t.id}" aria-label="開啟${t.name}"></button><div class="card-top"><span class="tool-icon">${icon(t.icon,20)}</span><h3>${esc(t.name)}</h3><button class="icon-button fav-btn ${S.favorites.includes(t.id)?'saved':''}" data-action="favorite" data-id="${t.id}" aria-label="${S.favorites.includes(t.id)?'移除':'加入'}常用：${t.name}" aria-pressed="${S.favorites.includes(t.id)}">${icon('star',15)}</button></div><p>${esc(t.desc)}</p><div class="card-link"><span>${esc(t.example)}</span><span class="tag ${t.id==='excel'?'green':''}">${esc(t.tag)}</span>${icon('arrow',13)}</div></article>`).join(''):`<div class="no-results">${q?'沒有符合的工具，試試「公文」「統計」或「圖卡」。':'還沒有常用工具。點工具右上方的星號即可加入。'}</div>`}
function customFieldHTML([key,label,type,options],f){if(type==='select')return `<div class="field"><label for="f-${key}">${label}</label><select class="select" id="f-${key}" data-field="${key}">${options.map(o=>`<option ${f[key]===o?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`;return `<div class="field"><label for="f-${key}">${label}</label>${type==='textarea'?`<textarea class="textarea" id="f-${key}" data-field="${key}" placeholder="${esc(options)}">${esc(f[key])}</textarea>`:`<input class="input" id="f-${key}" data-field="${key}" value="${esc(f[key])}" placeholder="${esc(options)}" maxlength="500">`}</div>`}
function workspaceHTML(){if(S.toolId==='excel')return Workbench.excel();const t=currentTool(),f=getForm();if(t.id==='official'&&window.OfficeCases?.isActive())return window.OfficeCases.render();if(window.LocalTools?.has(t.id))return LocalTools.render(t);return `<button class="back-link" data-action="home">${icon('back',13)}回到工作桌</button><div class="workspace-title"><span class="tool-icon">${icon(t.icon,25)}</span><h1>${esc(t.name)}</h1></div><p class="workspace-description">${esc(t.desc)} ${t.id==='excel'?'上傳表格後，可預覽所有工作表、拆分地址、分類統計與清除重複資料。':t.id==='design'?'文字公告可在下方直接預覽及下載 PNG。':'依固定格式與本機工具完成工作。'}</p><div class="workspace-summary"><span><span class="status-dot"></span>${t.tag}</span><span>繁體中文</span><span>可儲存工作草稿</span></div><div class="workspace-grid"><section class="panel form-panel"><form id="work-form"><div class="form-section-label"><span class="step-number">1</span>說明這次要做的事<button type="button" class="subtle" style="margin-left:auto;font-size:10px" data-action="sample">放入範例</button></div><div class="field"><label for="f-title">工作名稱 <small>方便之後找回</small></label><input class="input" id="f-title" data-field="title" value="${esc(f.title)}" placeholder="例如：這週的活動宣傳" maxlength="100"></div><div class="field"><label for="f-objective">這次想完成什麼？</label><textarea class="textarea" id="f-objective" data-field="objective" placeholder="${esc(t.objective)}" maxlength="10000">${esc(f.objective)}</textarea></div>${t.fields.map(x=>customFieldHTML(x,f)).join('')}<div class="form-section-label"><span class="step-number">2</span>提供原始資料</div><div class="field"><label for="f-material">原稿／活動資料／補充資訊</label><textarea class="textarea material" id="f-material" data-field="material" placeholder="貼上原文，或補充已確認的資訊、參考格式與不可修改的內容。" maxlength="100000">${esc(f.material)}</textarea></div><label class="dropzone" id="dropzone">${icon('upload',22)}<strong>拖曳檔案到這裡，或點一下選檔</strong><small>XLSX、CSV、TXT、DOCX、PDF、圖片 · 單檔上限 20 MB</small><input type="file" id="file-input" multiple accept=".xlsx,.csv,.tsv,.txt,.md,.json,.docx,.pdf,.png,.jpg,.jpeg,.webp" aria-label="上傳工作資料"></label><div class="file-list" id="file-list"></div>${S.attachmentNotice?`<p class="file-note">這份草稿原有 ${S.attachmentNotice} 個附件，請重新選取原檔。</p>`:''}<div id="workbook-area"></div>${t.id==='excel'?`<div id="excel-no-file" class="instruction-card"><h4>從你的檔案開始</h4><p>上傳 XLSX 或 CSV 後，可選工作表與標題列，再選擇要做的處理。也可以先用範例試一遍。</p><button class="secondary" style="margin-top:10px" type="button" data-action="sample-excel">${icon('table',14)}載入範例表格</button></div>`:''}${t.id==='design'?`<div id="card-area" class="local-panel"><div class="local-title"><h3>文字公告預覽</h3><span class="tag green">可下載 PNG</span></div><div id="card-note" class="render-note"></div><div class="card-preview"><canvas id="card-canvas" aria-label="文字公告預覽"></canvas></div><button type="button" class="secondary" data-action="download-card">${icon('download',14)}下載公告 PNG</button></div>`:''}${t.id==='documents'?`<div class="instruction-card"><h4>文件內容可先在這裡取出</h4><p>可讀取 PDF 最多 300 頁的文字、DOCX 正文及表格、純文字與 XLSX 全部工作表。掃描 PDF 若沒有文字層，需先以其他 OCR 工具轉成文字。</p><button type="button" class="secondary" style="margin-top:10px" data-action="download-extracted">${icon('download',14)}匯出已讀取文字</button></div>`:''}<div class="form-actions"><button type="submit" class="primary">${icon('clipboard',16)}產生結果與操作說明${icon('arrow',15)}</button><button type="button" class="secondary" data-action="save-draft">${icon('folder',14)}存草稿</button><button type="button" class="subtle" data-action="reset">清空</button></div><div class="field-hint">草稿儲存在這個瀏覽器，原始附件不會一併保存。</div></form></section><aside class="panel result-panel"><div class="result-heading"><h2>工作結果</h2><span class="tag">瀏覽器內完成</span></div><div class="result-body" id="result-body">${emptyOutputHTML()}</div></aside></div>`}
function invalidateOutput(){S.output='';const el=document.getElementById('result-body');if(el)el.innerHTML=emptyOutputHTML()}
function emptyOutputHTML(){return `<div class="result-empty"><div class="empty-icon">${icon('file',25)}</div><strong>把資料放好，直接完成工作。</strong><p>選擇情境、填入欄位，再產生可編輯的結果。<br>Excel 與圖卡也可直接使用下方操作區。</p></div><div class="callout">依固定模板、逐字規則與本機檔案工具運作，不呼叫 AI API。未提供的事實請自行核對並補入。</div>`}
function renderOutput(){const el=document.getElementById('result-body');if(!el)return;if(S.toolId==='excel'&&el.closest('details'))el.closest('details').open=true;const site=S.toolId==='website';el.innerHTML=`<p class="render-note">${site?'下方是網頁原始碼，可預覽或下載。':'內容已產生，可直接修改。PDF 匯出以影像排版；編輯文字請選 Word。'}</p><label class="visually-hidden" for="local-result">編輯工作結果</label><textarea id="local-result" class="case-draft-text local-result" spellcheck="false">${esc(S.output)}</textarea><div class="output-actions"><button class="primary" data-action="copy">${icon('copy',13)}複製</button><button class="secondary" data-action="download-packet">下載 TXT</button>${site?'<button class="secondary" data-local="site-preview">預覽網頁</button><button class="secondary" data-local="site-download">下載 HTML</button>':'<button class="secondary" data-local="result-word">下載 Word</button><button class="secondary" data-local="result-pdf">下載 PDF</button>'}</div>${site?'<iframe id="site-preview" title="產生的資訊網頁" sandbox="allow-scripts allow-popups" hidden></iframe>':''}`;}
function draftsHTML(){return `<div class="greeting-line"><div><div class="eyebrow">PICK UP WHERE YOU LEFT OFF</div><h1>我的工作草稿</h1><p class="page-subtitle">把背景和需求留好，下次就能接著做。共 ${S.drafts.length} 份草稿。</p></div>${S.drafts.length?`<button class="secondary" data-action="export-drafts">${icon('download',14)}備份全部草稿</button>`:''}</div>${S.drafts.length?`<div class="draft-grid">${S.drafts.map(d=>{const t=TOOLS.find(x=>x.id===d.toolId)||TOOLS[0];return `<article class="draft-card"><div class="card-top"><span class="tool-icon">${icon(t.icon,18)}</span><h3>${esc(d.form.title||t.name)}</h3></div><div class="draft-meta">${esc(t.short)} · ${esc(localDate(new Date(d.updatedAt)))}</div><p>${esc(d.form.objective||'尚未填寫需求')}</p><div class="draft-actions"><button class="primary" data-action="load-draft" data-id="${esc(d.id)}">接著做${icon('arrow',12)}</button><button class="icon-button" data-action="delete-draft" data-id="${esc(d.id)}" aria-label="刪除草稿：${esc(d.form.title||t.name)}">${icon('trash',15)}</button></div></article>`}).join('')}</div>`:`<div class="empty-page">${icon('folder',38)}<h2>先留下一件正在做的事</h2><p>在任何工具裡填寫需求，再按「存草稿」就會出現在這裡。</p><button class="primary" data-action="home">回工作桌挑一個工具${icon('arrow',14)}</button></div>`}<p class="footer-note">${icon('leaf',12)}草稿儲存在目前瀏覽器；備份不包含原始附件。清除網站資料會移除本機草稿。</p>`}
function openTool(id,objective){if(!TOOLS.some(t=>t.id===id))return;S.view='workspace';S.toolId=id;S.output='';S.excelResult=null;S.sheetIndex=0;S.headerRow=1;S.attachmentNotice=0;getForm();S.output=getForm()._result||'';if(objective)getForm().objective=objective;S.recent=[{id,at:Date.now()},...S.recent.filter(x=>x.id!==id)].slice(0,6);writeStore('recent',S.recent);location.hash=`tool-${id}`;render();window.scrollTo(0,0)}
function openHome(){S.view='home';location.hash='home';render();window.scrollTo(0,0)}
function findTool(text){const rules=[['excel',/excel|xlsx|csv|樞紐|公式|郵遞|依年齡|統計.*人數|拆.*地址|查表|去重|重複資料|下拉選單/i],['official',/公文|函稿|簽辦|備查|補送附件|來文|補助|核銷|核撥|存查/],['design',/圖卡|海報|製圖|修圖|QR.?code|配色/i],['reply',/回覆|回信|訊息|民眾.*問|信件/],['debug',/錯誤|失敗|排錯|直播|金鑰|workflow|github actions/i],['website',/網站|網頁|地圖|開發|工具/],['research',/查詢|查證|搜尋|查找|官方.*規則|選手.*得名/],['documents',/PDF|Word|轉檔|文件|整理.*表格|整併/i],['social',/貼文|文案|社群|FB|IG|宣傳|短影音/i]];return rules.find(([,re])=>re.test(text))?.[0]||'documents'}
function getFiles(){return S.files[S.toolId]||[]}
function renderFiles(){const el=document.getElementById('file-list');if(!el)return;el.innerHTML=getFiles().map(f=>`<div class="file-row">${icon(f.imageURL?'image':f.sheets?'sheet':'file',16)}<div><strong>${esc(f.name)}</strong><small>${(f.file.size/1024).toFixed(1)} KB · ${esc(f.status)}</small></div><button type="button" class="icon-button" data-action="remove-file" data-id="${f.id}" aria-label="移除 ${esc(f.name)}">${icon('x',13)}</button></div>`).join('')}
function columnName(index){let n=index+1,r='';while(n>0){n--;r=String.fromCharCode(65+n%26)+r;n=Math.floor(n/26)}return r}
function columnIndex(s){return [...s.replace(/\d/g,'')].reduce((n,c)=>n*26+c.charCodeAt(0)-64,0)-1}
function parseCSV(text,delimiter){text=text.replace(/^\uFEFF/,'');if(!delimiter){const line=text.split(/\r?\n/)[0]||'';delimiter=(line.match(/\t/g)||[]).length>(line.match(/,/g)||[]).length?'\t':',';if(delimiter===','&&!line.includes(',')&&line.includes(';'))delimiter=';'}const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else if(!quoted&&cell.length){cell+='"'}else quoted=!quoted;}else if(c===delimiter&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v!==''))rows.push(row);row=[];cell=''}else cell+=c;}if(cell||row.length){row.push(cell);rows.push(row)}if(quoted)throw Error('CSV 引號未配對，請檢查原檔。');return rows}
function csvEncode(rows){return '\uFEFF'+rows.map(row=>row.map(v=>{let s=String(v??'');if(/^(?:\s*[=+@-]|[\t\r])/.test(s)&&!(typeof v==='number'&&Number.isFinite(v)))s="'"+s;return /[",\r\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s}).join(',')).join('\r\n')}
function xmlDoc(text){if(text.length>50_000_000)throw Error('工作表過大，請先拆分檔案。');if(/<!DOCTYPE|<!ENTITY/i.test(text))throw Error('不支援此 XML 格式。');const xml=new DOMParser().parseFromString(text,'application/xml');if(xml.getElementsByTagName('parsererror').length)throw Error('檔案 XML 格式無法解析。');return xml}
const nodes=(el,name)=>Array.from(el.getElementsByTagNameNS('*',name));
async function readXLSX(file){
 const zip=await JSZip.loadAsync(await file.arrayBuffer());
 const get=async path=>{const e=zip.file(path);if(!e)throw Error('找不到工作簿內容，請確認為 .xlsx 檔案。');return xmlDoc(await e.async('string'))};
 const wb=await get('xl/workbook.xml'),rels=await get('xl/_rels/workbook.xml.rels');
 const relMap=Object.fromEntries(nodes(rels,'Relationship').map(e=>[e.getAttribute('Id'),e.getAttribute('Target')]));
 let shared=[];if(zip.file('xl/sharedStrings.xml'))shared=nodes(await get('xl/sharedStrings.xml'),'si').map(si=>nodes(si,'t').map(t=>t.textContent).join(''));
 let dateStyle=new Set();if(zip.file('xl/styles.xml')){const styles=await get('xl/styles.xml');const fmts=new Map(nodes(styles,'numFmt').map(n=>[+n.getAttribute('numFmtId'),n.getAttribute('formatCode')]));const xfs=nodes(styles,'cellXfs')[0];if(xfs)Array.from(xfs.children).forEach((n,i)=>{const id=+n.getAttribute('numFmtId');const fmt=(fmts.get(id)||'').replace(/"[^"]*"|\[[^\]]*\]|\\./g,'');if((id>=14&&id<=22)||(id>=45&&id<=47)||/[ymdhis]/i.test(fmt))dateStyle.add(i)});}
 const date1904=nodes(wb,'workbookPr')[0]?.getAttribute('date1904')==='1';const sheets=[];
 for(const sh of nodes(wb,'sheet')){let path=relMap[sh.getAttribute('r:id')||sh.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id')];if(!path)continue;path=path.startsWith('/')?path.slice(1):'xl/'+path;path=path.split('/').reduce((a,p)=>{if(p==='..')a.pop();else if(p!=='.')a.push(p);return a},[]).join('/');const xml=await get(path);const rows=[];let totalCells=0,missingCache=0;
  for(const r of nodes(xml,'row')){const rowIndex=(+r.getAttribute('r')||rows.length+1)-1;if(rowIndex>50000)throw Error('目前支援每張表 50,000 列以內，請先拆分。');const row=[];for(const cell of nodes(r,'c')){if(++totalCells>500000)throw Error('此工作表儲存格過多，請先拆分。');const col=columnIndex(cell.getAttribute('r')||`A${rowIndex+1}`);if(col>2000)throw Error('目前支援 2,000 欄以內的工作表。');const type=cell.getAttribute('t');const raw=nodes(cell,'v')[0]?.textContent??'';let value='';if(type==='s')value=shared[+raw]??'';else if(type==='inlineStr')value=nodes(cell,'t').map(t=>t.textContent).join('');else if(type==='b')value=raw==='1'?'TRUE':'FALSE';else if(type==='str'||type==='e')value=raw;else if(raw!==''){value=Number(raw);if(!Number.isFinite(value))value=raw;else if(dateStyle.has(+cell.getAttribute('s'))){const day=Math.floor(value);const date=new Date(((date1904?day+1462:day)-25569)*86400000);value=Number.isNaN(date.getTime())?raw:date.toISOString().slice(0,10)}}else if(nodes(cell,'f').length){missingCache++;value='（公式結果未儲存）'}row[col]=value;}
   rows[rowIndex]=Array.from({length:row.length},(_,i)=>row[i]??'');
  }const dense=Array.from({length:rows.length},(_,i)=>rows[i]||[]);while(dense.length&&!dense.at(-1).some(v=>v!==''))dense.pop();sheets.push({name:sh.getAttribute('name')||'工作表',rows:dense,missingCache});
 }if(!sheets.length)throw Error('檔案裡沒有可讀取的工作表。');return sheets;
}
async function readPDF(file){const pdfjs=await import('./vendor/pdf.mjs');pdfjs.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf.worker.mjs',location.href).href;const pdf=await pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false}).promise;let parts=[];try{for(let i=1;i<=Math.min(pdf.numPages,300);i++){const page=await pdf.getPage(i);const content=await page.getTextContent();parts.push(`【第 ${i} 頁】\n`+content.items.map(x=>x.str+(x.hasEOL?'\n':' ')).join(''));}return {text:parts.join('\n\n'),pages:pdf.numPages,limit:Math.min(pdf.numPages,300),empty:parts.join('').replace(/【第 \d+ 頁】/g,'').trim().length<5}}finally{await pdf.destroy()}}
async function readDOCX(file){const zip=await JSZip.loadAsync(await file.arrayBuffer());const entry=zip.file('word/document.xml');if(!entry)throw Error('無法找到 DOCX 正文。');const xml=xmlDoc(await entry.async('string'));return nodes(xml,'p').map(p=>nodes(p,'t').map(t=>t.textContent).join('')).join('\n')}
async function addFiles(fileList){invalidateOutput();const toolId=S.toolId;if(!S.files[toolId])S.files[toolId]=[];for(const file of fileList){if(file.size>20*1024*1024){toast(`${file.name} 超過 20 MB，請先縮小檔案。`);continue}if(S.files[toolId].length>=60){toast('一次最多加入 60 個檔案。');break}const f={id:String(++fileSequence),file,name:file.name,status:'讀取中…',text:''};S.files[toolId].push(f);if(S.toolId===toolId)renderFiles();try{const ext=file.name.split('.').pop().toLowerCase();if(ext==='xlsx'){f.sheets=await readXLSX(file);f.status=`已讀取 ${f.sheets.length} 張工作表`}else if(['csv','tsv'].includes(ext)){const buf=await file.arrayBuffer();let text;try{text=new TextDecoder('utf-8',{fatal:true}).decode(buf)}catch{text=new TextDecoder('big5').decode(buf)}f.sheets=[{name:file.name.replace(/\.[^.]+$/,''),rows:parseCSV(text,ext==='tsv'?'\t':undefined)}];f.status=`已讀取 ${Math.max(0,f.sheets[0].rows.length-1)} 筆資料`}else if(['txt','md','json'].includes(ext)){f.text=await file.text();f.status='已讀取文字'}else if(ext==='docx'){f.text=await readDOCX(file);f.status='已讀取正文與表格文字'}else if(ext==='pdf'){const p=await readPDF(file);f.text=p.text;f.status=p.empty?'沒有可讀取文字層；可保留原頁合併':`已讀取 ${p.limit}／${p.pages} 頁文字`;f.pdfPages=p.pages;f.pdfLimit=p.limit;}else if(['png','jpg','jpeg','webp'].includes(ext)){f.imageURL=URL.createObjectURL(file);f.status='已加入圖片，可製作圖片文件或覆蓋文字'}else f.status='不支援讀取此格式';}catch(e){f.status='讀取未完成：'+(e.message||'請檢查檔案格式');f.error=true}if(f.sheets){S.workbookFiles[toolId]=f.id;S.sheetIndex=0;S.headerRow=1;S.excelResult=null;S.excelOptions={}}if(S.toolId===toolId&&S.view==='workspace'){renderFiles();renderWorkbook();if(S.toolId==='design')renderCard()}}}
function workbookFile(){const fs=getFiles().filter(f=>f.sheets);return fs.find(f=>f.id===S.workbookFiles[S.toolId])||fs[0]}
function sheetData(){const f=workbookFile();if(!f)return null;const sh=f.sheets[Math.min(S.sheetIndex,f.sheets.length-1)];const hi=Math.max(0,Math.min(S.headerRow-1,Math.max(0,sh.rows.length-1)));const width=sh.rows.slice(hi).reduce((n,row)=>Math.max(n,row.length),0);const headers=Array.from({length:width},(_,i)=>String(sh.rows[hi]?.[i]??'').trim()||`欄 ${columnName(i)}`);const data=sh.rows.slice(hi+1).filter(r=>r.some(v=>v!==''&&v!=null)).map(r=>Array.from({length:width},(_,i)=>r[i]??''));return {file:f,sh,headers,data,hi,width}}
function renderWorkbook(){const area=document.getElementById('workbook-area');if(!area)return;const d=sheetData();const nofile=document.getElementById('excel-no-file');if(nofile)nofile.hidden=!!d;if(!d){area.innerHTML='';window.Workbench?.refreshExcel();return}const files=getFiles().filter(f=>f.sheets);area.innerHTML=`<section class="workbook-panel"><div class="local-title"><h3>表格預覽</h3><span class="tag green">本機讀取</span></div>${files.length>1?`<div class="field"><label for="workbook-select">資料檔案</label><select class="select" id="workbook-select">${files.map(f=>`<option value="${f.id}" ${f===d.file?'selected':''}>${esc(f.name)}</option>`).join('')}</select></div>`:''}<div class="sheet-tabs">${d.file.sheets.map((sh,i)=>`<button type="button" class="sheet-tab ${S.sheetIndex===i?'active':''}" data-action="sheet" data-index="${i}">${esc(sh.name)}</button>`).join('')}</div><div class="inline-options"><label for="header-row">標題在第幾列？</label><input class="input" type="number" id="header-row" min="1" max="${Math.max(1,d.sh.rows.length)}" value="${S.headerRow}"><span>第 ${S.headerRow} 列作為欄位名稱</span></div>${tableHTML(d.headers,d.data.slice(0,8),true,d.hi+2)}<p class="sheet-info">共 ${d.data.length.toLocaleString()} 筆資料、${d.width} 欄 · 預覽前 ${Math.min(8,d.data.length)} 筆 · 已讀取 ${d.file.sheets.length} 張工作表</p>${d.sh.missingCache?`<div class="callout amber">有 ${d.sh.missingCache} 格公式未儲存結果，請先在 Excel 開啟、重新計算並儲存後再上傳。</div>`:''}${S.toolId==='excel'?excelOptionsHTML(d):''}<p class="field-hint">XLSX 讀取已儲存的儲存格值；不執行巨集、不重新計算公式。匯出 CSV 保留資料值，版面與公式請在原檔編輯。</p></section>`;if(S.toolId==='excel'&&S.excelResult)renderExcelResult();window.Workbench?.refreshExcel()}
function tableHTML(headers,rows,numbers=false,start=2){return `<div class="table-wrap"><table class="data-table"><thead><tr>${numbers?'<th class="row-num">列</th>':''}${headers.map((h,i)=>`<th>${numbers?`<small>${columnName(i)} · </small>`:''}${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map((row,ri)=>`<tr>${numbers?`<td class="row-num">${start+ri}</td>`:''}${headers.map((_,i)=>`<td title="${esc(row[i]??'')}">${esc(row[i]??'')}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length+(numbers?1:0)}">沒有資料列。</td></tr>`}</tbody></table></div>`}
function excelOptionsHTML(d){const o=S.excelOptions;const fieldOptions=(v,none=false)=>`${none?'<option value="-1">不使用</option>':''}${d.headers.map((h,i)=>`<option value="${i}" ${+v===i?'selected':''}>${columnName(i)} 欄 · ${esc(h)}</option>`).join('')}`;return `<div class="local-options"><div class="field"><label for="excel-operation">這份表格想怎麼處理？</label><select class="select" id="excel-operation"><option value="guide" ${!o.operation||o.operation==='guide'?'selected':''}>先評估做法與操作步驟</option><option value="address" ${o.operation==='address'?'selected':''}>拆分郵遞區號與地址</option><option value="stats" ${o.operation==='stats'?'selected':''}>分類統計人數／加總</option><option value="dedupe" ${o.operation==='dedupe'?'selected':''}>清除重複資料</option></select></div>${o.operation==='address'?`<div class="field"><label for="excel-addressCol">哪一欄是含郵遞區號的地址？</label><select class="select" id="excel-addressCol" data-excel="addressCol">${fieldOptions(o.addressCol??Math.max(0,d.headers.findIndex(h=>/地址/.test(h))))}</select></div>`:o.operation==='stats'?`<div class="field-row"><div class="field"><label for="excel-groupCol">列分類</label><select class="select" id="excel-groupCol" data-excel="groupCol">${fieldOptions(o.groupCol??0)}</select></div><div class="field"><label for="excel-crossCol">欄分類（可選）</label><select class="select" id="excel-crossCol" data-excel="crossCol">${fieldOptions(o.crossCol??-1,true)}</select></div></div><div class="field-row"><div class="field"><label for="excel-aggregate">統計方式</label><select class="select" id="excel-aggregate" data-excel="aggregate"><option value="count" ${o.aggregate!=='sum'?'selected':''}>計算資料筆數（一列一筆）</option><option value="sum" ${o.aggregate==='sum'?'selected':''}>加總數值欄位</option></select></div><div class="field"><label for="excel-valueCol">加總哪一欄？</label><select class="select" id="excel-valueCol" data-excel="valueCol" ${o.aggregate!=='sum'?'disabled':''}>${fieldOptions(o.valueCol??0)}</select></div></div><label class="checkbox-label"><input type="checkbox" id="excel-ageBuckets" data-excel="ageBuckets" ${o.ageBuckets?'checked':''}>列分類為年齡，套用明確級距</label><p class="field-hint">年齡級距：未滿 18、18–29、30–44、45–64、65 歲以上。未選取時保留原始分類。</p>`:o.operation==='dedupe'?`<div class="field"><label for="excel-keyCol">依據什麼判斷重複？</label><select class="select" id="excel-keyCol" data-excel="keyCol"><option value="-1">整列內容完全相同</option>${fieldOptions(o.keyCol??-1)}</select><p class="field-hint">保留首次出現的資料；單欄比對時，空白值各自保留。</p></div>`:`<p class="render-note">可先在上方描述需求，再按「評估與教學」。會盤點實際欄位，建議適用的方法與檢查順序。</p>`}<button class="secondary" type="button" data-action="run-excel">${icon(o.operation&&o.operation!=='guide'?'table':'clipboard',14)}${o.operation&&o.operation!=='guide'?'執行處理並看教學':'評估與教學'}</button><div id="excel-result"></div></div>`}
function splitAddress(value){const str=String(value??'').trim();const m=str.match(/^[\[［【]\s*(\d{3}(?:\d{2,3})?)\s*[\]］】]\s*(.*)$/)||str.match(/^(\d{3}(?:\d{2,3})?)\s+(.+)$/);return m?{postal:m[1],address:m[2],matched:true}:{postal:'',address:str,matched:false}}
function ageBucket(value){const s=String(value??'').trim();if(!s||!/^\d+(?:\.\d+)?$/.test(s))return '未填／無效';const n=Number(s);if(n<0||n>130)return '未填／無效';return n<18?'未滿18歲':n<30?'18–29歲':n<45?'30–44歲':n<65?'45–64歲':'65歲以上'}
function aggregateRows(data,headers,o){const gi=+o.groupCol||0,ci=o.crossCol==null?-1:+o.crossCol,vi=+o.valueCol||0;const groups=new Map(),crosses=[],crossSet=new Set();let skipped=0;for(const row of data){const group=o.ageBuckets?ageBucket(row[gi]):String(row[gi]??'').trim()||'（未填）';const cross=ci<0?'統計值':String(row[ci]??'').trim()||'（未填）';let amount=1;if(o.aggregate==='sum'){const raw=String(row[vi]??'').trim().replace(/,/g,'');if(raw===''||!Number.isFinite(Number(raw))){skipped++;continue}amount=Number(raw)}if(!crossSet.has(cross)){crossSet.add(cross);crosses.push(cross)}if(!groups.has(group))groups.set(group,new Map());groups.get(group).set(cross,(groups.get(group).get(cross)||0)+amount)}if(o.ageBuckets){const order=['未滿18歲','18–29歲','30–44歲','45–64歲','65歲以上','未填／無效'];const sorted=[...groups].sort((a,b)=>order.indexOf(a[0])-order.indexOf(b[0]));groups.clear();sorted.forEach(([k,v])=>groups.set(k,v))}const rows=[...groups].map(([k,v])=>[k,...crosses.map(c=>v.get(c)||0),[...v.values()].reduce((a,b)=>a+b,0)]);const total=['合計',...crosses.map(c=>rows.reduce((a,r)=>a+r[crosses.indexOf(c)+1],0)),rows.reduce((a,r)=>a+r.at(-1),0)];return {headers:[o.ageBuckets?'年齡級距':headers[gi],...crosses, '合計'],rows:[...rows,total],skipped}}
function runExcel(){invalidateOutput();const d=sheetData();if(!d||!d.data.length){toast('請先選擇有資料的工作表。');return}const o=S.excelOptions;const operation=o.operation||'guide';if(operation==='guide'){const goal=getForm().objective||'',address=/地址|郵遞|拆分/.test(goal),stats=/統計|人數|分類|加總/.test(goal),dedupe=/重複|去重/.test(goal);S.excelResult={kind:'guide',title:'先看資料，再選方法',summary:`工作表「${d.sh.name}」共有 ${d.data.length} 筆，欄位：${d.headers.map((h,i)=>columnName(i)+'欄 '+h).join('、')}。`,steps:[`確認標題位於第 ${d.hi+1} 列；資料從第 ${d.hi+2} 列開始。`,address?'地址與郵遞區號混在同欄：改選「拆分郵遞區號與地址」，指定地址欄，再執行。':stats?'分類統計適合樞紐分析表：改選「分類統計人數／加總」，指定列分類、欄分類與統計方式。':dedupe?'改選「清除重複資料」，先決定用整列或指定欄位判斷；保留首次出現的資料。':'列出你要的輸出欄位：拆欄用文字函數，分類計數或加總用樞紐分析表，清理重複用移除重複項。','統計人數時先確認一列是否代表一人；性別代碼與年齡級距由你指定，不自行推定。','執行後先核對來源筆數、空白值及合計，再下載完整結果。','若是查表比對：Microsoft 365 可用 XLOOKUP；舊版可用 INDEX 配合 MATCH。先確認查找鍵值型態一致、對照表沒有重複鍵。'],formulas:[]};renderExcelResult();return}
 const range=`A${d.hi+1}:${columnName(d.width-1)}${d.sh.rows.length}`;let result;
 if(operation==='address'){const ci=o.addressCol!=null?+o.addressCol:Math.max(0,d.headers.findIndex(h=>/地址/.test(h)));let unmatched=0;const rows=d.data.map(row=>{const p=splitAddress(row[ci]);if(!p.matched)unmatched++;return [...row,p.postal,p.address]});const letter=columnName(ci),first=d.hi+2;const cell=`${letter}${first}`;result={kind:'table',title:'地址與郵遞區號已拆分',summary:`已處理 ${rows.length} 筆；${unmatched} 筆沒有辨識到支援的郵遞區號格式，郵遞區號留白並保留原地址。`,headers:[...d.headers,'郵遞區號（拆分）','純地址（拆分）'],rows,steps:[`在「${d.sh.name}」原資料右側新增「郵遞區號」與「純地址」兩欄。`,`若原始資料都是 [804]地址 這種半形中括號格式，在第一筆資料（原地址位於 ${cell}）旁輸入下方兩個公式。`,`將兩格公式向下填滿到最後一筆。原格式不同的列需另行確認；此處匯出的 CSV 也支援全形括號與「郵遞區號 空白 地址」格式。`,'核對未辨識資料；若要固定結果，可複製新欄後選擇性貼上為「值」。'],formulas:[`=IFERROR(MID(${cell},2,FIND("]",${cell})-2),"")`,`=IFERROR(MID(${cell},FIND("]",${cell})+1,LEN(${cell})),${cell})`]};}
 if(operation==='stats'){const aggregation=aggregateRows(d.data,d.headers,o);const gi=+o.groupCol||0,ci=o.crossCol==null?-1:+o.crossCol;const group=d.headers[gi];result={kind:'table',title:o.aggregate==='sum'?'分類加總已完成':'分類統計已完成',summary:`來源 ${d.data.length} 筆資料。${o.aggregate==='sum'?`已略過 ${aggregation.skipped} 筆空白或非數值資料。`:'每列計為 1 筆；同一人出現多列時會各自計算。'}${o.ageBuckets?'已依畫面所列的年齡級距分組。':'分類保留原值；數字代碼未自行轉成性別。'}`,...aggregation,steps:[`在 Excel 開啟「${d.sh.name}」，確認標題位於第 ${d.hi+1} 列，資料範圍為 ${range}。`,o.ageBuckets?`先在資料右方建立「年齡級距」輔助欄，以 ${columnName(gi)} 欄年齡輸入下方公式並填滿。`:`選取資料範圍，點「插入」→「樞紐分析表」→「新增工作表」。`,o.ageBuckets?'選取包含新輔助欄的完整資料，點「插入」→「樞紐分析表」。':`把「${group}」拖到「列」。`,o.ageBuckets?'把「年齡級距」拖到「列」。':ci>=0?`把「${d.headers[ci]}」拖到「欄」。`:'不需欄分類時，「欄」區域留白。',...(o.ageBuckets&&ci>=0?[`把「${d.headers[ci]}」拖到「欄」。`]:[]),o.aggregate==='sum'?`把「${d.headers[+o.valueCol||0]}」拖到「值」，點「值欄位設定」選「加總」，並確認該欄為數值。`:`新增一欄「筆數」，每筆輸入 1，納入資料來源後拖到「值」，設定為「加總」，避免空白姓名造成少算。`,`將總計與來源資料核對。${o.aggregate==='sum'?'留意未填與非數值資料。':`此處合計應為 ${d.data.length} 筆。`}`],formulas:o.ageBuckets?[`=IFERROR(IF(OR(${columnName(gi)}${d.hi+2}="",NOT(ISNUMBER(${columnName(gi)}${d.hi+2})),${columnName(gi)}${d.hi+2}<0,${columnName(gi)}${d.hi+2}>130),"未填／無效",IF(${columnName(gi)}${d.hi+2}<18,"未滿18歲",IF(${columnName(gi)}${d.hi+2}<30,"18–29歲",IF(${columnName(gi)}${d.hi+2}<45,"30–44歲",IF(${columnName(gi)}${d.hi+2}<65,"45–64歲","65歲以上"))))),"未填／無效")`]:[]};}
 if(operation==='dedupe'){const ki=o.keyCol==null?-1:+o.keyCol;const seen=new Set();let removed=0;const rows=d.data.filter((row,index)=>{const value=ki<0?row:String(row[ki]??'');if(ki>=0&&value==='')return true;const key=JSON.stringify(value);if(seen.has(key)){removed++;return false}seen.add(key);return true});result={kind:'table',title:'重複資料已整理',summary:`原有 ${d.data.length} 筆，移除 ${removed} 筆重複，保留 ${rows.length} 筆。${ki>=0?'比對欄位：'+d.headers[ki]+'；空白值各自保留。':'依整列內容比對，保留首次出現的資料。'}`,headers:d.headers,rows,steps:[`先備份原檔，再選取「${d.sh.name}」的資料範圍 ${range}。`,'點「資料」→「移除重複項」，勾選「我的資料有標題」。',ki<0?'勾選全部欄位，依整列資料判斷重複。':`只勾選「${d.headers[ki]}」欄；原資料中的空白值若需各自保留，先將空白列暫時另存。`,'執行後核對保留與移除筆數，確認沒有刪除需要保留的紀錄。']};}
 if(!result)return;S.excelResult=result;renderExcelResult();toast('已完成本機處理，下方附有 Excel 操作步驟。');}
function renderExcelResult(){const el=document.getElementById('excel-result');const r=S.excelResult;if(!el||!r)return;el.innerHTML=`<div class="analysis-box"><h4>${esc(r.title)}</h4><p>${esc(r.summary)}</p>${r.kind==='table'?`<div style="margin-top:12px">${tableHTML(r.headers,r.rows.slice(0,10))}</div><p class="field-hint">結果預覽前 ${Math.min(10,r.rows.length)} 列；下載包含全部 ${r.rows.length} 列。</p>`:''}<ol>${r.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>${(r.formulas||[]).map(x=>`<code>${esc(x)}</code>`).join('')}${r.kind==='table'?`<button class="secondary" type="button" data-action="download-excel">${icon('download',13)}下載完整結果 CSV</button><button class="secondary" type="button" data-local="excel-xlsx">下載 XLSX</button>`:''}<button class="subtle" type="button" data-action="excel-to-packet">把步驟放到右側編輯${icon('arrow',12)}</button></div>`}
function fileContext(f){if(f.sheets)return `檔案：${f.name}\n狀態：${f.status}\n${f.sheets.map(sh=>{const rows=sh.rows;return `工作表「${sh.name}」：共 ${rows.length} 列（含可能的標題列）。以下是前 12 列預覽，並非完整資料：\n${rows.slice(0,12).map((r,i)=>`${i+1}: ${r.map((v,j)=>`${columnName(j)}=${String(v).replace(/\n/g,' ')}`).join(' | ')}`).join('\n')}`}).join('\n\n')}`;return `檔案：${f.name}\n狀態：${f.status}${f.text?'\n已讀取文字（最多 10,000 字；完整內容請讀原檔）：\n'+f.text.slice(0,10000):''}`}
function generatePacket(){if(window.LocalTools?.has(S.toolId))return LocalTools.generate();if(S.toolId==='excel'){if(!S.excelResult)runExcel();const r=S.excelResult;S.output=r?`${r.title}\n\n${r.summary}\n\n${r.steps.map((s,i)=>`${i+1}. ${s}`).join('\n\n')}\n\n${(r.formulas||[]).join('\n')}`:'請先加入 Excel 或 CSV，或載入範例表格，再選擇處理方式。';}else if(S.toolId==='design'){renderCard();const f=getForm();S.output=[f.headline,f.cardBody,f.cardFooter,'下載前核對：日期、時間、地點、繁體中文字與原圖保留區域。'].filter(Boolean).join('\n\n')}getForm()._result=S.output;renderOutput();return true}
let preparedDownloadURL='';
function download(content,name,type='text/plain;charset=utf-8'){const blob=content instanceof Blob?content:new Blob([content],{type});if(preparedDownloadURL)URL.revokeObjectURL(preparedDownloadURL);preparedDownloadURL=URL.createObjectURL(blob);document.getElementById('download-ready')?.remove();const box=document.createElement('div');box.id='download-ready';box.className='callout';box.setAttribute('role','status');const text=document.createElement('p');text.textContent='檔案已準備；若沒有自動下載，可按下方連結。';const a=document.createElement('a');a.href=preparedDownloadURL;a.download=name;a.className='secondary';a.textContent='下載 '+name;box.append(text,a);(document.getElementById('result-body')||document.getElementById('main')).append(box);a.click()}

function safeName(s){return String(s||'工作內容').replace(/[\\/:*?"<>|\u0000-\u001f]/g,'_').slice(0,70)}
async function copyText(text,message='已複製內容。'){try{await navigator.clipboard.writeText(text);toast(message)}catch{const area=document.createElement('textarea');area.value=text;area.style.position='fixed';area.style.opacity='0';document.body.append(area);area.select();const ok=document.execCommand('copy');area.remove();toast(ok?message:'複製未完成，請選取右側內容手動複製。')}}
function renderCard(){const canvas=document.getElementById('card-canvas');if(!canvas)return;const f=getForm();const original=f.designMode==='修改既有圖卡／保留原框';const cardArea=document.getElementById('card-area');cardArea.querySelector('.card-preview').hidden=original;cardArea.querySelector('[data-action="download-card"]').hidden=original;document.getElementById('card-note').textContent=original?'請加入原圖，選取文字覆蓋範圍。':'此處可製作新的文字公告。文字超出時會提示縮短，下載前請核對內容。';if(original){ImageEditor.render().catch(e=>toast('圖片未完成：'+e.message));return;}const controls=document.getElementById('image-controls');if(controls)controls.hidden=true;const dims=f.size.includes('1920')?[1080,1920]:f.size.includes('1080 × 1080')?[1080,1080]:[1200,630];canvas.width=dims[0];canvas.height=dims[1];const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height;ctx.fillStyle='#f6f3e9';ctx.fillRect(0,0,w,h);const m=w*.065;ctx.fillStyle='#235b4e';ctx.fillRect(m,m,48,5);ctx.font=`500 ${Math.round(w*.017)}px "Microsoft JhengHei",sans-serif`;ctx.fillText('INFORMATION  /  公告',m+64,m+10);ctx.strokeStyle='#cad6bf';ctx.lineWidth=2;ctx.strokeRect(m,m+50,w-2*m,h-2*m-50);const title=f.headline||'請填入公告標題';const body=f.cardBody||'把這次要公告的重點\n清楚地寫在這裡';const footer=f.cardFooter||'';const contentWidth=w-2*m-65;const lines=(text,size)=>{ctx.font=`${size}px "Microsoft JhengHei",sans-serif`;const out=[];String(text).split('\n').forEach(p=>{let line='';for(const c of p){if(ctx.measureText(line+c).width>contentWidth&&line){out.push(line);line=c}else line+=c}out.push(line)});return out};let titleSize=Math.round(w*.055),bodySize=Math.round(w*.031),footSize=Math.round(w*.021);let tl,bl,fl,required;for(let i=0;i<8;i++){tl=lines(title,titleSize);bl=lines(body,bodySize);fl=footer?lines(footer,footSize):[];required=tl.length*titleSize*1.4+bl.length*bodySize*1.8+fl.length*footSize*1.6+110;if(required<h-2*m-90)break;titleSize*=.9;bodySize*=.9;footSize*=.9}let y=m+100;ctx.textBaseline='top';ctx.fillStyle='#235b4e';ctx.font=`700 ${titleSize}px "Microsoft JhengHei",sans-serif`;tl.forEach(line=>{ctx.fillText(line,m+33,y);y+=titleSize*1.4});y+=26;ctx.fillStyle='#bc8b39';ctx.fillRect(m+33,y,38,4);y+=33;ctx.fillStyle='#3a5145';ctx.font=`${bodySize}px "Microsoft JhengHei",sans-serif`;bl.forEach(line=>{ctx.fillText(line,m+33,y);y+=bodySize*1.8});ctx.fillStyle='#78836d';ctx.font=`${footSize}px "Microsoft JhengHei",sans-serif`;let fy=Math.max(y+30,h-m-35-fl.length*footSize*1.6);fl.forEach(line=>{ctx.fillText(line,m+33,fy);fy+=footSize*1.6});if(Math.max(y,fy)>h-m-10){document.getElementById('card-note').textContent='文字超出公告範圍，請縮短內容後再下載。';cardArea.querySelector('[data-action="download-card"]').disabled=true}else cardArea.querySelector('[data-action="download-card"]').disabled=false;}
function saveDraft(){const f={...getForm()};let id=f._draftId;if(!id)id=typeof crypto.randomUUID==='function'?crypto.randomUUID():`draft-${Date.now()}-${Math.random().toString(36).slice(2,10)}`;f._draftId=id;getForm()._draftId=id;const d={id,toolId:S.toolId,form:f,updatedAt:Date.now(),attachmentCount:getFiles().length};S.drafts=[d,...S.drafts.filter(x=>x.id!==id)].slice(0,60);if(writeStore('drafts',S.drafts)){const badge=document.querySelector('.nav-badge');if(badge)badge.textContent=S.drafts.length;toast('草稿已儲存；原始附件請下次重新加入。')}}
function showSettings(){const d=document.getElementById('settings-dialog');d.innerHTML=`<form id="settings-form"><div class="dialog-heading"><h2>我的使用偏好</h2><button class="icon-button" type="button" data-action="close-settings" aria-label="關閉偏好設定">${icon('x')}</button></div><p class="render-note">保留你常用的寫作與排版備忘。實際產出依各工具欄位與固定版型；文字可再手動修改。</p><div class="field"><label for="pref-name">你的稱呼</label><input id="pref-name" name="name" class="input" value="${esc(S.prefs.name)}" required maxlength="12"></div><div class="field"><label for="pref-tone">文字語氣</label><input id="pref-tone" name="tone" class="input" value="${esc(S.prefs.tone)}" maxlength="150"></div><div class="field"><label for="pref-length">篇幅與排版</label><input id="pref-length" name="length" class="input" value="${esc(S.prefs.length)}" maxlength="150"></div><div class="field"><label for="pref-notes">其他固定要求</label><textarea id="pref-notes" name="notes" class="textarea" maxlength="2000">${esc(S.prefs.notes)}</textarea></div><div class="dialog-actions"><button class="secondary" type="button" data-action="close-settings">取消</button><button class="primary" type="submit">儲存偏好${icon('check',14)}</button></div></form>`;d.showModal()}
function showHelp(){const d=document.getElementById('help-dialog');d.innerHTML=`<div class="dialog-heading"><h2>這張辦公桌怎麼用？</h2><button class="icon-button" data-action="close-help" aria-label="關閉使用說明">${icon('x')}</button></div><p>你的舊案、定型稿與常用工作格式，整合成9個入口。運作不需要 AI API。</p><ol><li>公文：匯入私人資料包後，搜尋原案、查看簽函，或直接填定型稿。</li><li>社群與回覆：選情境、填入事實，產生固定句型後直接編輯。</li><li>Excel：加入檔案，確認工作表與標題列，再拆欄、統計或去重；結果附步驟與下載。</li><li>文件：完整列出工作表，匯出 Word、PDF、XLSX，或合併原 PDF。</li><li>圖卡：製作文字公告，或在原圖選矩形覆蓋文字；矩形外保持原圖。</li><li>查證與排錯：整理你提供的來源、錯誤與手冊原文；不自動進行網路查證。</li><li>網站：填資料產生固定版型資訊頁，可預覽並下載 HTML。</li></ol><p>結果可在網站修改、複製、下載。公文與草稿留在目前瀏覽器；換電腦或清除資料前，請在「資料與備份」匯出。</p><div class="dialog-actions"><button class="primary" data-action="close-help">知道了</button></div>`;d.showModal()}
function loadSample(){const t=currentTool(),f=getForm();f.title='範例｜'+t.short;f.objective=t.objective;const samples={official:'【示意資料，請勿直接發文】\n本案原函已發出，因系統異常未附上競賽規程，需要補送附件。\n原函日期及字號：待填\n附件名稱：競賽規程',social:'【示意活動】\n活動名稱：社區運動體驗日\n時間、地點、費用：尚待確認\n報名方式：額滿開班\n希望邀請沒有運動經驗的市民參加。',design:'【示意公告】\n場地進行整理，下午暫停開放。\n晚場維持 19:00–21:00。\n日期與場地名稱須再確認。',reply:'【示意訊息】\n對方詢問：申請案目前是否已經核定？\n已確認情形：承辦已完成送審，目前由長官審核中，尚未核定。',documents:'【示意需求】\n請依主要資料的分類整理成表格。\n每份附件都要納入，若有無法讀取內容請列出。',research:'【示意查證問題】\n第三方使用者在粉專貼文底下留言外部連結，是否會計入粉專的連結分享額度？\n需要官方說明及資料日期。',website:'【示意工具需求】\n民眾可以依行政區、運動項目查找課程。\n需要清楚顯示地點、時間與報名方式。\n資料來源及更新方式待確認。',debug:'【示意問題】\n自動更新網站的工作流程執行失敗。\n請根據另附的執行紀錄，找出失敗步驟及要修改的檔案。',excel:'【示意資料】\n想依年齡與性別統計報名人數。\n先確認年齡級距與性別代碼，再教我建立樞紐分析表。'};f.material=samples[t.id];if(t.id==='design'){f.headline='開放時間調整';f.cardBody='下午暫停開放\n晚場開放 19:00–21:00';f.cardFooter='造成不便，敬請見諒。'}render();toast('已放入示意內容，可自行修改。')}
async function loadExcelSample(){const content='姓名,年齡,性別,競賽種類,地址,報名費\n範例甲,15,女,田徑,[804]高雄市鼓山區示意路1號,200\n範例乙,26,男,游泳,[802]高雄市苓雅區示意路2號,200\n範例丙,38,女,田徑,[807]高雄市三民區示意路3號,300\n範例丁,52,男,游泳,[830]高雄市鳳山區示意路4號,300\n範例戊,68,女,田徑,[811]高雄市楠梓區示意路5號,200\n範例己,27,男,田徑,[804]高雄市鼓山區示意路6號,200\n範例己,27,男,田徑,[804]高雄市鼓山區示意路6號,200\n範例庚,42,女,游泳,尚未提供,300';await addFiles([new File([content],'範例_活動報名.csv',{type:'text/csv'})]);getForm().objective='請依年齡級距與性別統計報名資料，並教我在 Excel 建立樞紐分析表。';getForm().title='範例｜活動報名統計';S.excelOptions={operation:'stats',groupCol:1,crossCol:2,aggregate:'count',ageBuckets:true};render();toast('已載入示意表格，所有姓名與地址皆為範例。')}

document.addEventListener('submit',async e=>{if(e.target.id==='quick-task'){e.preventDefault();const text=document.getElementById('quick-input').value.trim();if(text)openTool(findTool(text),text)}if(e.target.id==='work-form'){e.preventDefault();generatePacket()}if(e.target.id==='settings-form'){e.preventDefault();const data=Object.fromEntries(new FormData(e.target));data.name=data.name.trim()||'千禧';S.prefs={...defaults,...S.prefs,...data};if(writeStore('prefs',S.prefs)){document.getElementById('settings-dialog').close();render();toast('偏好備忘已儲存。')}}});
document.addEventListener('input',e=>{const field=e.target.dataset.field;if(field){getForm()[field]=e.target.value;delete getForm()._result;S.output='';const result=document.getElementById('result-body');if(result)result.innerHTML=emptyOutputHTML();if(S.toolId==='design'){clearTimeout(cardTimer);cardTimer=setTimeout(renderCard,80)}}if(e.target.id==='tool-search'){S.search=e.target.value;if(S.view!=='home'){S.view='home';location.hash='home';render();const input=document.getElementById('tool-search');input.focus();input.setSelectionRange?.(input.value.length,input.value.length);}else document.getElementById('tools-grid').innerHTML=cardsHTML()}});
document.addEventListener('change',async e=>{if(e.target.id==='file-input'){await addFiles(e.target.files);e.target.value=''}if(e.target.id==='header-row'){invalidateOutput();const d=sheetData();const n=+e.target.value;S.headerRow=Math.max(1,Math.min(Math.max(1,d?.sh.rows.length||1),Number.isFinite(n)?n:1));S.excelResult=null;S.excelOptions={};renderWorkbook()}if(e.target.id==='workbook-select'){invalidateOutput();S.workbookFiles[S.toolId]=e.target.value;S.sheetIndex=0;S.headerRow=1;S.excelResult=null;S.excelOptions={};renderWorkbook()}if(e.target.id==='excel-operation'){invalidateOutput();S.excelOptions={operation:e.target.value};S.excelResult=null;renderWorkbook()}if(e.target.dataset.excel){invalidateOutput();const key=e.target.dataset.excel;S.excelOptions[key]=e.target.type==='checkbox'?e.target.checked:e.target.value;S.excelResult=null;const result=document.getElementById('excel-result');if(result)result.innerHTML='';if(key==='aggregate')renderWorkbook()}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=b.dataset.id;switch(action){
 case 'home':e.preventDefault();openHome();break;
 case 'tool':openTool(id);break;
 case 'drafts':S.view='drafts';location.hash='drafts';render();window.scrollTo(0,0);break;
 case 'favorite':S.favorites=S.favorites.includes(id)?S.favorites.filter(x=>x!==id):[...S.favorites,id];writeStore('favorites',S.favorites);document.getElementById('tools-grid').innerHTML=cardsHTML();break;
 case 'filter':S.filter=b.dataset.filter;document.querySelectorAll('.filter-btn').forEach(el=>el.classList.toggle('active',el.dataset.filter===S.filter));document.getElementById('tools-grid').innerHTML=cardsHTML();break;
 case 'quick-example':openTool(id,TOOLS.find(x=>x.id===id).objective);break;
 case 'settings':showSettings();break;
 case 'close-settings':document.getElementById('settings-dialog').close();break;
 case 'help':showHelp();break;
 case 'close-help':document.getElementById('help-dialog').close();break;
 case 'open-menu':document.querySelector('.sidebar').classList.add('open');document.querySelector('.mobile-overlay').classList.add('open');break;
 case 'close-menu':document.querySelector('.sidebar').classList.remove('open');document.querySelector('.mobile-overlay').classList.remove('open');break;
 case 'sample':loadSample();break;
 case 'sample-excel':await loadExcelSample();break;
 case 'save-draft':saveDraft();break;
 case 'load-draft':{const d=S.drafts.find(x=>x.id===id);if(d){S.forms[d.toolId]={...d.form};if(d.toolId==='official')window.OfficeCases?.restoreDraft(d);(S.files[d.toolId]||[]).forEach(f=>{if(f.imageURL)URL.revokeObjectURL(f.imageURL)});S.files[d.toolId]=[];S.excelOptions={};openTool(d.toolId);S.attachmentNotice=d.attachmentCount||0;render();toast('已開啟草稿，原始附件請重新選取。')}break;}
 case 'delete-draft':if(confirm('確定刪除這份工作草稿？')){S.drafts=S.drafts.filter(x=>x.id!==id);writeStore('drafts',S.drafts);render();toast('草稿已刪除。')}break;
 case 'export-drafts':download(JSON.stringify({app:'千禧的辦公桌',exportedAt:new Date().toISOString(),drafts:S.drafts},null,2),'辦公桌_草稿備份.json','application/json');break;
 case 'reset':if(confirm('清空這個工具目前的內容與附件？已儲存草稿會保留。')){delete S.forms[S.toolId];getFiles().forEach(f=>{if(f.imageURL)URL.revokeObjectURL(f.imageURL)});S.files[S.toolId]=[];S.output='';S.excelResult=null;S.excelOptions={};S.attachmentNotice=0;render()}break;
 case 'remove-file':{const f=getFiles().find(x=>x.id===id);if(f?.imageURL)URL.revokeObjectURL(f.imageURL);S.files[S.toolId]=getFiles().filter(x=>x.id!==id);S.output='';S.excelResult=null;renderFiles();renderWorkbook();if(S.toolId==='design')renderCard();document.getElementById('result-body').innerHTML=emptyOutputHTML();break;}
 case 'sheet':invalidateOutput();S.sheetIndex=+b.dataset.index;S.headerRow=1;S.excelOptions={};S.excelResult=null;renderWorkbook();break;
 case 'run-excel':runExcel();break;
 case 'excel-to-packet':if(!getForm().objective){getForm().objective=currentTool().objective;document.getElementById('f-objective').value=getForm().objective}generatePacket();break;
 case 'download-excel':if(S.excelResult?.rows)download(csvEncode([S.excelResult.headers,...S.excelResult.rows]),safeName(getForm().title||S.excelResult.title)+'.csv','text/csv;charset=utf-8');break;
 case 'copy':if(S.output)await copyText(S.output);break;
 case 'download-packet':if(S.output)download(S.output,safeName(getForm().title||currentTool().name)+'.txt');break;
 case 'download-extracted':{const fs=getFiles();if(!fs.length){toast('請先加入檔案。');break}const text=fs.map(f=>f.sheets?`【${f.name}】\n${f.sheets.map(sh=>`工作表：${sh.name}\n${sh.rows.map(r=>r.map(v=>String(v??'')).join('\t')).join('\n')}`).join('\n\n')}`:`【${f.name}】\n讀取狀態：${f.status}\n${f.text||'沒有可匯出的文字。'}`).join('\n\n────────────\n\n');download(text,safeName(getForm().title||'文件')+'_已讀取文字.txt');break;}
 case 'download-card':{const canvas=document.getElementById('card-canvas');if(canvas)canvas.toBlob(blob=>{if(blob)download(blob,safeName(getForm().headline||'文字公告')+'.png')},'image/png');break;}
}});
document.addEventListener('dragover',e=>{const dz=e.target.closest('#dropzone');if(dz){e.preventDefault();dz.classList.add('dragging')}});
document.addEventListener('dragleave',e=>e.target.closest('#dropzone')?.classList.remove('dragging'));
document.addEventListener('drop',async e=>{const dz=e.target.closest('#dropzone');if(dz){e.preventDefault();dz.classList.remove('dragging');await addFiles(e.dataTransfer.files)}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)){e.preventDefault();document.getElementById('tool-search')?.focus()}});
window.addEventListener('hashchange',()=>{const hash=location.hash.slice(1);if(hash==='home'&&S.view!=='home'){S.view='home';render()}else if(hash==='drafts'&&S.view!=='drafts'){S.view='drafts';render()}else if(hash.startsWith('tool-')){const id=hash.slice(5);if(TOOLS.some(t=>t.id===id)&&(S.view!=='workspace'||S.toolId!==id))openTool(id)}});
const initial=location.hash.slice(1);if(initial.startsWith('tool-')&&TOOLS.some(t=>t.id===initial.slice(5)))openTool(initial.slice(5));else{if(initial==='drafts')S.view='drafts';render()}
